/** Only BUY+CLUTCH may consume an approved feature's allocation cap. */
export function strategyAllocationCheck({manifest,run,account,quote,now}){
 const plan=manifest.data.strategyPlan;if(!isMindStrategyPlanActive(plan,now)||run.decision.action!=='buy'||run.decision.stance!=='clutch'||plan.allocation.opportunityModuleId===null)return null;
 const evaluation=plan.graph?.schemaVersion===2?run.strategyEvaluation:run.rawRequest?.state?.strategyEvaluation??run.strategyEvaluation;assertStrategyEvaluation(evaluation,{manifest,marketAsOf:run.asOf,instrumentId:run.instrumentId,now});
 const feature=strategyOpportunityFeature(plan,evaluation),p=strategyOpportunityModule(plan).parameters;
 check(feature?.ready&&finite(feature.allocationFactor)&&feature.allocationFactor>0&&feature.allocationFactor<=1,'CLUTCH_OPPORTUNITY_REQUIRED','승인한 기회 조건을 충족한 계산 결과를 확인하세요.',409);
 check(HASH.test(quote.rawSha256??''),'CLUTCH_QUOTE_SOURCE_REQUIRED','실행 현재가의 실제 응답 해시를 확인하세요.',409);
 const episode=strategyHoldingEpisode(account,run.instrumentId,now);let winner=null;
 if(episode){check(evaluation.episode?.episodeId===episode.episodeId,'CLUTCH_EPISODE_CHANGED','현재 연속 보유와 판단에 사용한 보유를 대조하세요.',409);const policy=account.costPolicy;check(policy?.feeBps===10&&policy.slippageBps===5,'CLUTCH_COST_REQUIRED','모의 계좌의 확인된 수수료·슬리피지를 사용하세요.',409);const netLiquidationValue=episode.quantity*quote.price*(1-policy.slippageBps/10000)*(1-policy.feeBps/10000),netProfit=netLiquidationValue-episode.costBasis,netProfitRatio=netProfit/episode.costBasis;winner={...episode,quoteAsOf:quote.asOf,quoteReceivedAt:quote.receivedAt,quoteRawSha256:quote.rawSha256??null,feeBps:policy.feeBps,slippageBps:policy.slippageBps,netLiquidationValue,netProfit,netProfitRatio,requiredProfitRatio:p.addProfitThreshold};check(netProfit>0&&netProfitRatio>=p.addProfitThreshold,'CLUTCH_WINNER_ONLY','비용 후 평가 이익이 승인한 증액 조건을 충족할 때 추가 매수하세요.',409);}
 return {policyVersion:plan.allocationPolicyVersionId,planId:plan.planId,planVersionId:plan.planVersionId,planHash:evaluation.planHash,featureOutputHash:evaluation.outputHash,moduleVersion:feature.implementationVersion,parametersVersionId:feature.parametersVersionId,allocationFactor:feature.allocationFactor,strategyMaxExposure:plan.allocation.strategyMaxExposure,winner};
}
